// Получаем входные данные
const input = msg.payload;

// Проверяем, что пришёл ожидаемый объект
if (!input || !Array.isArray(input.numbers)) {
    msg.payload = { error: "ожидался объект с полем numbers (массив)" };
    return msg;
}

// Извлекаем поля (деструктуризация)
const { numbers, limit, name } = input;

// Считаем сумму всех чисел циклом for
let sum = 0;
for (let i = 0; i < numbers.length; i++) {
    sum += numbers[i];
}

// Фильтруем массив: оставляем числа больше limit
const filtered = [];
for (let i = 0; i < numbers.length; i++) {
    if (numbers[i] > limit) {
        filtered.push(numbers[i]);
    }
}

// Формируем объект-результат
const result = {
    author: name,
    original: numbers,
    limit: limit,
    sum: sum,
    aboveLimit: filtered,
    count: filtered.length,
    timestamp: new Date().toISOString()
};

// Возвращаем сообщение с payload-объектом
msg.payload = result;
return msg;
